changeSet.sql:
CREATE TABLE organization_documents ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
organization_id uuid NOT NULL, type varchar(32) NOT NULL CHECK (type IN ('CAC_CERTIFICATE', 'CAC_STATUS_REPORT', 'TIN', 'PROOF_OF_ADDRESS', 'SCUML_CERTIFICATE', 'STATE_REGULATOR_PERMIT', 'REDAN_CERTIFICATE', 'OTHER')), file_name varchar(255) NOT NULL, size bigint NOT NULL, status varchar(32) NOT NULL CHECK (status IN ('PENDING', 'VERIFIED', 'REJECTED')), rejection_reason varchar(255), uploaded_at timestamp(6) with time zone NOT NULL, -- No file storage (S3/MinIO) integration exists yet — only -- metadata is persisted today. This will hold the eventual -- object key once one lands. storage_key varchar(255),
PRIMARY KEY (id) );
COMMENT ON TABLE organization_documents IS 'Land title documents (C of O, R of O, Governor''s Consent, Gazette, survey plan) are deliberately NOT stored here. Title evidence is per-estate, not per-company — a company can hold clean title on one estate and none on another. Title lives on the estate record and is captured at estate creation.';
